import bridging.SatuSehatNutritionOrderPayload;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.time.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Synthetic clinical instructions only. No production config, database, tokens, or API. */
public class SatuSehatNutritionOrderPayloadTest {
    private final Clock clock=Clock.fixed(Instant.parse("2026-11-13T08:00:00Z"),ZoneOffset.UTC);
    private ObjectNode review(){
        ObjectNode r=SatuSehatNutritionOrderPayload.JSON.createObjectNode();r.put("intent","order");r.put("status","active");r.put("doctor","test-doctor");r.put("issued","2026-11-12 09:00:00");r.put("start","2026-11-12 10:00:00");r.put("end","");r.put("instruction","Instruksi sintetis sesuai dokumentasi.");r.put("reviewed",true);
        r.putArray("diets").add(SatuSehatNutritionOrderPayload.DIETS.get(2).json());return r;
    }
    private ObjectNode build(ObjectNode r){return SatuSehatNutritionOrderPayload.build(r,"test-patient","test-encounter","test-practitioner",clock);}
    private void held(Runnable action){try{action.run();fail("Must stop without transmitting");}catch(IllegalArgumentException expected){}}
    @Test public void postUsesR4ReferencesAndOralDiet(){ObjectNode p=build(review());assertEquals("NutritionOrder",p.path("resourceType").asText());assertEquals("Patient/test-patient",p.path("patient").path("reference").asText());assertEquals("Encounter/test-encounter",p.path("encounter").path("reference").asText());assertEquals("Practitioner/test-practitioner",p.path("orderer").path("reference").asText());assertFalse(p.has("subject"));assertFalse(p.has("id"));assertTrue(p.path("oralDiet").has("instruction"));assertFalse(p.path("oralDiet").has("Instruction"));}
    @Test public void witaPreservesInstant(){ObjectNode p=build(review());assertEquals(Instant.parse("2026-11-12T01:00:00Z"),OffsetDateTime.parse(p.path("dateTime").asText()).toInstant());assertEquals("2026-11-12T10:00:00+08:00",p.path("oralDiet").path("schedule").get(0).path("repeat").path("boundsPeriod").path("start").asText());}
    @Test public void explicitUtcIsNotRelabeledAsWita(){ObjectNode r=review();r.put("issued","2026-11-12T01:00:00Z");assertEquals(Instant.parse("2026-11-12T01:00:00Z"),OffsetDateTime.parse(build(r).path("dateTime").asText()).toInstant());}
    @Test public void actualIssueAndEffectiveTimeRemainDistinct(){ObjectNode p=build(review());assertNotEquals(p.path("dateTime").asText(),p.path("oralDiet").path("schedule").get(0).path("repeat").path("boundsPeriod").path("start").asText());}
    @Test public void futureIssueHeldWithoutClamping(){ObjectNode r=review();r.put("issued","2026-11-14 09:00:00");held(()->build(r));assertEquals("2026-11-14 09:00:00",r.path("issued").asText());}
    @Test public void legitimateFutureScheduleNotClamped(){ObjectNode r=review();r.put("start","2026-11-14 09:00:00");assertEquals("2026-11-14T09:00:00+08:00",build(r).path("oralDiet").path("schedule").get(0).path("repeat").path("boundsPeriod").path("start").asText());}
    @Test public void juneThird2014BoundaryAccepted(){ObjectNode r=review();r.put("issued","2014-06-03T08:00:00+08:00");r.put("start","2014-06-03T09:00:00+08:00");build(r);}
    @Test public void beforeBoundaryHeld(){ObjectNode r=review();r.put("issued","2014-06-02 08:00:00");held(()->build(r));}
    @Test public void nonexistentCalendarDateHeld(){ObjectNode r=review();r.put("issued","2026-02-29 08:00:00");held(()->build(r));}
    @Test public void dateWithoutTimeHeld(){ObjectNode r=review();r.put("issued","2026-11-12");held(()->build(r));}
    @Test public void endBeforeStartHeld(){ObjectNode r=review();r.put("end","2026-11-12 09:30:00");held(()->build(r));}
    @Test public void startBeforeIssueHeld(){ObjectNode r=review();r.put("start","2026-11-12 08:30:00");held(()->build(r));}
    @Test public void cancelledDietUsesRevokedAndRealEnd(){ObjectNode r=review();r.put("status","revoked");r.put("end","2026-11-12 12:00:00");assertEquals("revoked",build(r).path("status").asText());}
    @Test public void completedNeedsExplicitEnd(){ObjectNode r=review();r.put("status","completed");held(()->build(r));r.put("end","2026-11-12 12:00:00");build(r);}
    @Test public void endOfCompletedDietCannotBeFuture(){ObjectNode r=review();r.put("status","completed");r.put("end","2026-11-14 12:00:00");held(()->build(r));}
    @Test public void wrongR4StatusStoppedHeld(){ObjectNode r=review();r.put("status","stopped");held(()->build(r));}
    @Test public void draftsCanBeValidatedButNotTransmitted(){ObjectNode r=review();r.put("status","draft");SatuSehatNutritionOrderPayload.validateReview(r,clock);held(()->build(r));}
    @Test public void proposalIsPreservedAsProposal(){ObjectNode r=review();r.put("intent","proposal");assertEquals("proposal",build(r).path("intent").asText());}
    @Test public void missingIntentNotInferredFromInstruction(){ObjectNode r=review();r.remove("intent");held(()->build(r));}
    @Test public void noImplicitDoctorOrReviewConfirmation(){ObjectNode r=review();r.put("doctor","");held(()->build(r));r.put("doctor","test-doctor");r.put("reviewed",false);held(()->build(r));}
    @Test public void emptyReferencesHeld(){for(String type:new String[]{"Patient","Encounter","Practitioner","Organization"})held(()->SatuSehatNutritionOrderPayload.ref(type,""));held(()->SatuSehatNutritionOrderPayload.ref("Patient","Patient/wrong"));}
    @Test public void noDietCannotProduceEmptyResource(){ObjectNode r=review();r.putArray("diets");held(()->build(r));}
    @Test public void nullRequiredClinicalTextHeld(){ObjectNode r=review();r.putNull("instruction");held(()->build(r));}
    @Test public void multipleDietsPreservedSeparately(){ObjectNode r=review();((ArrayNode)r.path("diets")).add(SatuSehatNutritionOrderPayload.DIETS.get(7).json());assertEquals(2,build(r).path("oralDiet").path("type").size());}
    @Test public void textureIsSeparateAndLocalNamePreserved(){ObjectNode r=review();ObjectNode texture=SatuSehatNutritionOrderPayload.TEXTURES.get(1).json();texture.put("confirmed",true);r.set("texture",texture);ObjectNode p=build(r);assertEquals("228059003",p.path("oralDiet").path("texture").get(0).path("modifier").path("coding").get(0).path("code").asText());assertTrue(p.path("oralDiet").path("instruction").asText().contains("Nasi Lembek"));assertEquals("386619000",p.path("oralDiet").path("type").get(0).path("coding").get(0).path("code").asText());}
    @Test public void candidateTextureNeedsConfirmation(){ObjectNode r=review();r.set("texture",SatuSehatNutritionOrderPayload.TEXTURES.get(0).json());held(()->build(r));}
    @Test public void tktpNotAutomaticallySameAsTprot(){ObjectNode r=review();r.putArray("diets").add(SatuSehatNutritionOrderPayload.DIETS.get(0).json());held(()->build(r));r.putArray("diets").add(SatuSehatNutritionOrderPayload.DIETS.get(1).json());held(()->build(r));}
    @Test public void genericRpDoesNotInventGrams(){ObjectNode r=review();r.putArray("diets").add(SatuSehatNutritionOrderPayload.DIETS.get(5).json());held(()->build(r));r.putArray("diets").add(SatuSehatNutritionOrderPayload.DIETS.get(12).json());assertEquals("OV000375",build(r).path("oralDiet").path("type").get(0).path("coding").get(0).path("code").asText());}
    @Test public void clearAndFullLiquidsNotCollapsed(){for(int i:new int[]{4,5}){ObjectNode r=review();ObjectNode texture=SatuSehatNutritionOrderPayload.TEXTURES.get(i).json();texture.put("confirmed",true);r.set("texture",texture);held(()->build(r));}}
    @Test public void maliciousTerminologySystemHeld(){ObjectNode r=review();((ObjectNode)r.path("diets").get(0)).put("system","https://unverified.invalid");held(()->build(r));}
    @Test public void noInventedEnergyProteinOrParenteralFields(){ObjectNode p=build(review());assertFalse(p.path("oralDiet").has("nutrient"));assertFalse(p.has("enteralFormula"));assertFalse(p.has("supplement"));assertFalse(p.has("identifier"));}
    @Test public void buildDoesNotAlterSourceReview(){ObjectNode r=review(),copy=r.deepCopy();build(r);assertEquals(copy,r);}
    @Test public void immutableSourceKeysDoNotCollideAcrossVisitsOrTimes(){assertEquals(SatuSehatNutritionOrderPayload.sourceKey("test-visit","2026-11-12 10:00:00"),SatuSehatNutritionOrderPayload.sourceKey("test-visit","2026-11-12 10:00:00"));assertNotEquals(SatuSehatNutritionOrderPayload.sourceKey("test-visit","2026-11-12 10:00:00"),SatuSehatNutritionOrderPayload.sourceKey("test-visit","2026-11-12 11:00:00"));}
    @Test public void putAllowsStatusChangeForSameInstruction(){ObjectNode before=build(review()),r=review();r.put("status","completed");r.put("end","2026-11-12 12:00:00");SatuSehatNutritionOrderPayload.verifyUpdate(build(r),before);}
    @Test public void putCannotPromoteProposalToOrder(){ObjectNode r=review();r.put("intent","proposal");ObjectNode before=build(r);held(()->SatuSehatNutritionOrderPayload.verifyUpdate(build(review()),before));}
    @Test public void putCannotReplaceClinicalReferences(){for(String field:new String[]{"patient","encounter","orderer"}){ObjectNode before=build(review());((ObjectNode)before.path(field)).put("reference","Other/wrong");held(()->SatuSehatNutritionOrderPayload.verifyUpdate(build(review()),before));}}
    @Test public void putCannotReattributeIssueTime(){ObjectNode before=build(review());before.put("dateTime","2026-11-12T00:00:00Z");held(()->SatuSehatNutritionOrderPayload.verifyUpdate(build(review()),before));}
    @Test public void updateAcceptsEquivalentTimezones(){ObjectNode before=build(review());before.put("dateTime","2026-11-12T01:00:00Z");SatuSehatNutritionOrderPayload.verifyUpdate(build(review()),before);}
    @Test public void wrongRemoteResourceHeld(){ObjectNode before=build(review());before.put("resourceType","Composition");held(()->SatuSehatNutritionOrderPayload.verifyUpdate(build(review()),before));}
    @Test public void allDateTimeFieldsIncludeZeroSeconds(){ObjectNode r=review();r.put("status","completed");r.put("end","2026-11-12 16:30:00");ObjectNode p=build(r);JsonNode period=p.path("oralDiet").path("schedule").get(0).path("repeat").path("boundsPeriod");String full="[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(Z|[+-][0-9]{2}:[0-9]{2})";assertTrue(p.path("dateTime").asText().matches(full));assertTrue(period.path("start").asText().matches(full));assertTrue(period.path("end").asText().matches(full));}
    @Test public void fractionalAndNonzeroSecondsArePreserved(){assertEquals("2026-11-12T09:00:17+08:00",SatuSehatNutritionOrderPayload.fhirTime("2026-11-12 09:00:17"));assertEquals("2026-11-12T09:00:00.125+08:00",SatuSehatNutritionOrderPayload.fhirTime("2026-11-12T09:00:00.125+08:00"));assertEquals("2026-11-12T01:00:00Z",SatuSehatNutritionOrderPayload.fhirTime("2026-11-12T01:00Z"));}
    @Test public void unsupportedFhirOffsetsHeld(){held(()->SatuSehatNutritionOrderPayload.fhirTime("2026-11-12T09:00:00+15:00"));held(()->SatuSehatNutritionOrderPayload.fhirTime("2026-11-12T09:00:00+08:00:30"));}
    @Test public void endedInstructionsCannotBeReactivated(){for(String status:new String[]{"completed","revoked","entered-in-error"}){ObjectNode old=build(review());old.put("status",status);held(()->SatuSehatNutritionOrderPayload.verifyUpdate(build(review()),old));}}
    @Test public void updatePreservesOtherServerClinicalFields(){ObjectNode old=build(review());old.putObject("meta").put("versionId","synthetic-version");old.putArray("note").addObject().put("text","Catatan sintetis tambahan");old.with("oralDiet").putArray("nutrient").addObject().putObject("amount").put("value",123).put("unit","g");ObjectNode r=review();r.put("instruction","Instruksi sintetis yang ditinjau ulang.");ObjectNode actual=SatuSehatNutritionOrderPayload.mergeUpdate(build(r),old);assertEquals(old.path("note"),actual.path("note"));assertEquals(old.path("oralDiet").path("nutrient"),actual.path("oralDiet").path("nutrient"));assertEquals(old.path("meta"),actual.path("meta"));assertEquals(r.path("instruction").asText(),actual.path("oralDiet").path("instruction").asText());}
    @Test public void textureChangeRequiresNewInstruction(){ObjectNode r=review();ObjectNode texture=SatuSehatNutritionOrderPayload.TEXTURES.get(1).json();texture.put("confirmed",true);r.set("texture",texture);ObjectNode old=build(r);held(()->SatuSehatNutritionOrderPayload.mergeUpdate(build(review()),old));}
    @Test public void dietChangeRequiresNewInstruction(){ObjectNode r=review();r.putArray("diets").add(SatuSehatNutritionOrderPayload.DIETS.get(7).json());ObjectNode old=build(review());held(()->SatuSehatNutritionOrderPayload.mergeUpdate(build(r),old));}
    @Test public void statusUpdatePreservesTextureFoodType(){ObjectNode r=review();ObjectNode texture=SatuSehatNutritionOrderPayload.TEXTURES.get(1).json();texture.put("confirmed",true);r.set("texture",texture);ObjectNode old=build(r);((ObjectNode)old.path("oralDiet").path("texture").get(0)).putObject("foodType").put("text","Jenis makanan sintetis");ObjectNode result=SatuSehatNutritionOrderPayload.mergeUpdate(build(r),old);assertEquals(old.path("oralDiet").path("texture").get(0).path("foodType"),result.path("oralDiet").path("texture").get(0).path("foodType"));}
    @Test public void startOfExistingPrescriptionCannotBeRewritten(){ObjectNode old=build(review()),r=review();r.put("start","2026-11-12 11:00:00");held(()->SatuSehatNutritionOrderPayload.verifyUpdate(build(r),old));}
    @Test public void errorsNeverEchoClinicalDetails(){String body="{\"issue\":[{\"expression\":[\"NutritionOrder.patient\",\"Patient/private-id\"],\"details\":{\"text\":\"private-name private-token RuleNumber: 10400\"}}]}";String safe=SatuSehatNutritionOrderPayload.safeError(body);assertTrue(safe.contains("NutritionOrder.patient"));assertTrue(safe.contains("10400"));assertFalse(safe.contains("private"));assertFalse(SatuSehatNutritionOrderPayload.safeError("private-secret").contains("private"));}
}
